// GitHub active branches (#402) — ahead/behind counts + merge status. Extracted from GitHubPulse's
// inline card into its own composable record; adds the loading skeleton the inline version didn't have.
import { CardHead, Avatar } from "@/shared/ui/charts";
import { Skeleton } from "@/shared/ui/feedback/Skeleton";
import { Stack } from "@/shared/ui/layout/Stack";
import { Grid } from "@/shared/ui/layout/Grid";
import { Row } from "@/shared/ui/layout/Row";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { Card } from "@/shared/ui/data/Card";

export interface GithubBranch { n: string; ahead: number; behind: number; status: "clean" | "stale" | "conflict"; owner?: string; bot?: boolean }
const BRANCH_STATUS: Record<GithubBranch["status"], { label: string; color: string }> = {
  clean: { label: "clean", color: "var(--success)" }, stale: { label: "stale", color: "var(--fg-dim)" }, conflict: { label: "conflict", color: "var(--danger)" },
};

const DEMO_BRANCHES: GithubBranch[] = [
  { n: "feature/export-endpoint", ahead: 4, behind: 1, status: "clean", owner: "octocat" },
  { n: "fix/credit-race", ahead: 2, behind: 6, status: "stale", owner: "hubot", bot: true },
];

export function Branches({ branches = DEMO_BRANCHES, loading = false }: { branches?: GithubBranch[]; loading?: boolean }) {
  if (loading) {
    return (
      <Card>
        <CardHead title="Active branches" hint="ahead/behind the default branch" />
        <Stack gap={1} style={{ borderRadius: 6, border: "1px solid var(--border-soft)", overflow: "hidden" }}>
          {Array.from({ length: 3 }).map((_, i) => (
            <Grid key={i} cols="1fr 70px 70px" gap={8} align="center" style={{ padding: "8px 11px", background: i % 2 ? "var(--bg-panel)" : "var(--bg-elev)" }}>
              <Row gap={7}>
                <Skeleton w={15} h={15} radius={99} />
                <Skeleton w="60%" h={11} />
              </Row>
              <Skeleton w={40} h={9} style={{ marginLeft: "auto" }} />
              <Skeleton w={50} h={9} style={{ marginLeft: "auto" }} />
            </Grid>
          ))}
        </Stack>
      </Card>
    );
  }
  if (!branches.length) return null;
  return (
    <Card>
      <CardHead title="Active branches" hint="ahead/behind the default branch"
        right={<Text as="span" mono size={10.5} tone="accent">{branches.length}</Text>} />
      <Stack gap={1} style={{ borderRadius: 6, border: "1px solid var(--border-soft)", overflow: "hidden" }}>
        {branches.map((b, i) => {
          const st = BRANCH_STATUS[b.status];
          return (
            <Grid key={b.n} className="hrow" cols="1fr 70px 70px" gap={8} align="center" style={{ padding: "8px 11px", fontSize: 11, background: i % 2 ? "var(--bg-panel)" : "var(--bg-elev)" }}>
              <Row gap={7} style={{ minWidth: 0 }}>
                {b.owner && <Avatar login={b.owner} bot={b.bot} size={15} />}
                <Box as="span" className="mono" style={{ color: "var(--fg)", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{b.n}</Box>
              </Row>
              <Text as="span" mono size={9.5} tone="dim">
                <Text as="span" tone="success">↑{b.ahead}</Text> <Text as="span" tone="danger">↓{b.behind}</Text>
              </Text>
              <Text as="span" mono size={9.5} style={{ textAlign: "right", color: st.color }}>● {st.label}</Text>
            </Grid>
          );
        })}
      </Stack>
    </Card>
  );
}
